  app.get('/api/leads',asyncRoute(async(req,res)=>{const where=['l.archived_at IS NULL'];const values:unknown[]=[new Date()];const add=(sql:string,value:unknown)=>{values.push(value);where.push(sql.replace('?',`$${values.length}`));};
    if(!isManager(req.user!.role))add('l.assigned_to=?',req.user!.id);
    const search=String(req.query.search||'').trim();if(search){values.push(`%${search}%`);const textAt=`$${values.length}`;const phone=cleanContact(search);if(phone){values.push(`%${phone}%`);where.push(`(l.name ILIKE ${textAt} OR l.contact LIKE $${values.length} OR l.address ILIKE ${textAt} OR l.reference_name ILIKE ${textAt})`);}else{where.push(`(l.name ILIKE ${textAt} OR l.address ILIKE ${textAt} OR l.reference_name ILIKE ${textAt})`);}}
    const type=String(req.query.type||'');if(['HOT','WARM','COLD'].includes(type))add('l.lead_type=?',type);
    const status=String(req.query.status||'');if(['ACTIVE','CONVERTED','INACTIVE'].includes(status))add('l.status=?',status);
    const workflow=String(req.query.workflow||'');if(workflowStatus.options.includes(workflow as any))add('l.workflow_status=?',workflow);
    const source=String(req.query.source||'');if(leadSource.options.includes(source as any))add('l.lead_source=?',source);
    const assigned=Number(req.query.assignedTo||0);if(isManager(req.user!.role)&&Number.isInteger(assigned)&&assigned>0)add('l.assigned_to=?',assigned);
    const from=String(req.query.dateFrom||'');if(/^\d{4}-\d{2}-\d{2}$/.test(from))add('l.enquiry_date>=?',from);
    const to=String(req.query.dateTo||'');if(/^\d{4}-\d{2}-\d{2}$/.test(to))add('l.enquiry_date<=?',to);
    const followup=String(req.query.followup||'');
    if(followup==='overdue')where.push('COALESCE(fs.overdue_count,0)>0');
    if(followup==='scheduled')where.push('COALESCE(fs.pending_count,0)>0');
    if(followup==='none')where.push('COALESCE(fs.pending_count,0)=0');
    const sortMap:Record<string,string>={newest:'l.created_at DESC',oldest:'l.created_at ASC',name:'l.name ASC',followup:'next_followup ASC NULLS LAST'};const sort=sortMap[String(req.query.sort||'newest')]||sortMap.newest;
    const channelPartnerId=Number(req.query.channelPartnerId||0);if(isManager(req.user!.role)&&Number.isInteger(channelPartnerId)&&channelPartnerId>0)add('l.channel_partner_id=?',channelPartnerId);
    const rows=(await db.query(`SELECT l.*,u.name assigned_name,cp.name channel_partner_name,fs.next_followup FROM leads l JOIN users u ON u.id=l.assigned_to LEFT JOIN channel_partners cp ON cp.id=l.channel_partner_id LEFT JOIN (SELECT lead_id,MIN(CASE WHEN status='PENDING' THEN scheduled_at END) next_followup,SUM(CASE WHEN status='PENDING' THEN 1 ELSE 0 END) pending_count,SUM(CASE WHEN status='PENDING' AND scheduled_at<$1 THEN 1 ELSE 0 END) overdue_count FROM followups GROUP BY lead_id) fs ON fs.lead_id=l.id WHERE ${where.join(' AND ')} ORDER BY ${sort}`,values)).rows;res.json({leads:rows});
  }));

