  app.post('/api/leads/:id/documents',asyncRoute(async(req,res)=>{const lead=(await db.query<any>(`SELECT id,assigned_to FROM leads WHERE id=$1 AND archived_at IS NULL${isManager(req.user!.role)?'':' AND assigned_to=$2'}`,isManager(req.user!.role)?[req.params.id]:[req.params.id,req.user!.id])).rows[0];if(!lead)return res.status(404).json({error:'Lead not found'});const parsed=z.object({documentType:z.string().trim().min(2).max(60),fileName:z.string().trim().min(1).max(255),mimeType:z.string().trim().min(3).max(100),data:z.string().min(1)}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:parsed.error.issues[0]?.message});const content=parsed.data.data.replace(/^data:[^;]+;base64,/,'');const buffer=Buffer.from(content,'base64');if(!buffer.length||buffer.length>5242880)return res.status(400).json({error:'Document must be between 1 byte and 5 MB'});const item=await transaction(db,async client=>{const document=(await client.query<any>('INSERT INTO lead_documents(lead_id,document_type,file_name,mime_type,file_size,file_data,uploaded_by) VALUES ($1,$2,$3,$4,$5,$6,$7) RETURNING id,lead_id,document_type,file_name,mime_type,file_size,created_at',[lead.id,parsed.data.documentType,parsed.data.fileName,parsed.data.mimeType,buffer.length,buffer,req.user!.id])).rows[0];await client.query("INSERT INTO lead_activities(lead_id,user_id,type,content,metadata) VALUES ($1,$2,'DETAILS_UPDATED',$3,$4)",[lead.id,req.user!.id,`Customer document uploaded: ${parsed.data.fileName}`,{documentId:document.id,documentType:parsed.data.documentType}]);await audit(client,req.user!.id,'LEAD_DOCUMENT_UPLOADED','LEAD',Number(lead.id),{documentId:document.id,documentType:parsed.data.documentType});return document;});res.status(201).json({document:item});}));

