  app.patch('/api/leads/:id',asyncRoute(async(req,res)=>{
    const current=(await db.query<any>(`SELECT * FROM leads WHERE id=$1${isManager(req.user!.role)?'':' AND assigned_to=$2'}`,isManager(req.user!.role)?[req.params.id]:[req.params.id,req.user!.id])).rows[0];
    if(!current)return res.status(404).json({error:'Lead not found'});
    const parsed=z.object({
      name:z.string().trim().min(2).max(100).optional(),
      contact:z.string().trim().regex(/^\+?[0-9]{10,15}$/,'Enter a valid 10–15 digit contact number').optional(),
      address:z.string().trim().max(500).optional(),
      referenceName:z.string().trim().max(150).optional(),
      leadType:leadType.optional(),
      leadSource:leadSource.optional(),
      workflowStatus:workflowStatus.optional(),
      assignedTo:z.coerce.number().int().positive().optional(),
      projectName:z.string().trim().max(150).optional(),
      enquiryDate:z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional(),
      enquiryTime:z.string().regex(/^\d{2}:\d{2}$/).optional()
    }).safeParse(req.body);
    if(!parsed.success)return res.status(400).json({error:parsed.error.issues[0]?.message});
    const p=parsed.data;
    if(p.workflowStatus&&p.workflowStatus!==current.workflow_status)return res.status(400).json({error:'Move stages from the Sales Pipeline so required outcomes are recorded'});
    if(p.assignedTo&&!isManager(req.user!.role))return res.status(403).json({error:'Only administrators and managers can reassign leads'});
    const assignedTo=p.assignedTo??current.assigned_to;
    if(!(await db.query('SELECT id FROM users WHERE id=$1 AND active=TRUE',[assignedTo])).rows[0])return res.status(400).json({error:'Select a valid assigned executive'});

    let nextContact = current.contact;
    if (p.contact) {
      nextContact = cleanContact(p.contact);
      if (nextContact !== current.contact) {
        const conflict = (await db.query<any>('SELECT id FROM leads WHERE contact=$1 AND id<>$2 AND archived_at IS NULL', [nextContact, current.id])).rows[0];
        if (conflict) return res.status(409).json({ error: 'Another lead with this contact number already exists' });
      }
    }

    const next={
      name:p.name??current.name,
      contact:nextContact,
      address:p.address??current.address,
      reference_name:p.referenceName!==undefined?p.referenceName:current.reference_name,
      lead_type:p.leadType??current.lead_type,
      lead_source:p.leadSource??current.lead_source,
      workflow_status:p.workflowStatus??current.workflow_status,
      assigned_to:assignedTo,
      project_name:p.projectName!==undefined?p.projectName:current.project_name,
      enquiry_date:p.enquiryDate??current.enquiry_date,
      enquiry_time:p.enquiryTime??current.enquiry_time
    };

    const diffs:string[] = [];
    if(next.name!==current.name) diffs.push(`Name: "${current.name}" → "${next.name}"`);
    if(next.contact!==current.contact) diffs.push(`Contact: ${current.contact} → ${next.contact}`);
    if(next.address!==current.address) diffs.push(`Address updated`);
    if(next.reference_name!==current.reference_name) diffs.push(`Reference: "${current.reference_name||'None'}" → "${next.reference_name||'None'}"`);
    if(next.lead_type!==current.lead_type) diffs.push(`Classification: ${current.lead_type} → ${next.lead_type}`);
    if(next.lead_source!==current.lead_source) diffs.push(`Source: ${current.lead_source} → ${next.lead_source}`);
    if(next.assigned_to!==current.assigned_to) diffs.push(`Assigned executive updated`);
    if(next.project_name!==current.project_name) diffs.push(`Project: "${next.project_name||'None'}"`);
    if(next.enquiry_date!==current.enquiry_date||next.enquiry_time!==current.enquiry_time) diffs.push(`Enquiry schedule updated`);

    await transaction(db,async client=>{
      await client.query(
        `UPDATE leads SET name=$1,contact=$2,address=$3,reference_name=$4,lead_type=$5,lead_source=$6,workflow_status=$7,assigned_to=$8,status=$9,project_name=$10,enquiry_date=$11,enquiry_time=$12,updated_at=CURRENT_TIMESTAMP WHERE id=$13`,
        [next.name,next.contact,next.address,next.reference_name,next.lead_type,next.lead_source,next.workflow_status,next.assigned_to,next.workflow_status==='WON'?'CONVERTED':next.workflow_status==='LOST'?'INACTIVE':'ACTIVE',next.project_name,next.enquiry_date,next.enquiry_time,req.params.id]
      );
      const activityContent = diffs.length ? `Lead details updated by ${req.user!.name}: ${diffs.join(', ')}` : 'Lead details updated';
      await client.query(
        'INSERT INTO lead_activities(lead_id,user_id,type,content,metadata) VALUES ($1,$2,$3,$4,$5)',
        [req.params.id,req.user!.id,next.lead_type!==current.lead_type&&diffs.length===1?'TYPE_CHANGED':'DETAILS_UPDATED',activityContent,{diffs,before:current,after:next}]
      );
      await audit(client,req.user!.id,'LEAD_UPDATED','LEAD',Number(req.params.id),{diffs,before:current,after:next});
    });

    res.json({lead:(await db.query('SELECT * FROM leads WHERE id=$1',[req.params.id])).rows[0]});
  }));

  app.delete('/api/leads/:id',asyncRoute(async(req,res)=>{if(!isManager(req.user!.role))return res.status(403).json({error:'Only administrators and managers can delete leads'});const lead=(await db.query<any>('SELECT id,name,archived_at FROM leads WHERE id=$1',[req.params.id])).rows[0];if(!lead||lead.archived_at)return res.status(404).json({error:'Lead not found'});const booking=(await db.query('SELECT id FROM plot_bookings WHERE lead_id=$1 AND status<>\'CANCELLED\' LIMIT 1',[req.params.id])).rows[0];if(booking)return res.status(409).json({error:'This lead has an active booking. Cancel the booking before deleting the lead.'});await transaction(db,async client=>{await client.query('UPDATE leads SET archived_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=$1',[req.params.id]);const followups=(await client.query<any>("UPDATE followups SET status='CANCELLED',updated_at=CURRENT_TIMESTAMP WHERE lead_id=$1 AND status='PENDING' RETURNING id",[req.params.id])).rows;for(const followup of followups)await client.query('UPDATE notifications SET is_read=TRUE WHERE followup_id=$1',[followup.id]);await audit(client,req.user!.id,'LEAD_DELETED','LEAD',Number(req.params.id),{name:lead.name});});res.status(204).end();}));

  app.post('/api/leads/:id/remarks',asyncRoute(async(req,res)=>{const parsed=z.object({remark:z.string().trim().min(1).max(1000)}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Remark is required'});const result=await db.query(`INSERT INTO lead_activities(lead_id,user_id,type,content) SELECT id,$2,'REMARK',$3 FROM leads WHERE id=$1${isManager(req.user!.role)?'':' AND assigned_to=$2'} RETURNING id`,[req.params.id,req.user!.id,parsed.data.remark]);if(!result.rows[0])return res.status(404).json({error:'Lead not found'});await audit(db,req.user!.id,'REMARK_ADDED','LEAD',Number(req.params.id));res.status(201).json({id:result.rows[0].id});}));
  app.post('/api/leads/:id/followups',asyncRoute(async(req,res)=>{const parsed=followupInput.safeParse(req.body);if(!parsed.success)return res.status(400).json({error:parsed.error.issues[0]?.message});const lead=(await db.query<any>(`SELECT id,assigned_to,workflow_status FROM leads WHERE id=$1${isManager(req.user!.role)?'':' AND assigned_to=$2'}`,isManager(req.user!.role)?[req.params.id]:[req.params.id,req.user!.id])).rows[0];if(!lead)return res.status(404).json({error:'Lead not found'});if(!['CONTACTED','FOLLOW_UP'].includes(lead.workflow_status))return res.status(400).json({error:'Follow-ups can only be scheduled after the lead has been contacted'});const item=await transaction(db,async client=>{if(lead.workflow_status==='CONTACTED'){await client.query("UPDATE leads SET workflow_status='FOLLOW_UP',pipeline_updated_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=$1",[lead.id]);await client.query("INSERT INTO lead_activities(lead_id,user_id,type,content,metadata) VALUES ($1,$2,'STAGE_CHANGED',$3,$4)",[lead.id,req.user!.id,`Contacted → Follow-up — ${parsed.data.remark}`,{fromStage:'CONTACTED',toStage:'FOLLOW_UP',scheduledAt:parsed.data.scheduledAt}]);}const followup=await upsertPipelineReminder(client,Number(req.params.id),lead.assigned_to,req.user!.id,'FOLLOW_UP',parsed.data.scheduledAt,parsed.data.remark);await audit(client,req.user!.id,'FOLLOWUP_SCHEDULED','FOLLOWUP',followup.id,{leadId:Number(req.params.id),scheduledAt:parsed.data.scheduledAt});return followup;});res.status(201).json({followup:item});}));

  app.get('/api/followups',asyncRoute(async(req,res)=>{await createDueNotifications(db,req.user!.id);const scope=String(req.query.scope||'today');const day=businessDay();const own=!isManager(req.user!.role);const params:unknown[]=own?[req.user!.id]:[];const position=()=>`$${params.length+1}`;let clause:string;if(scope==='upcoming'){const at=position();params.push(day.end);clause=`f.status='PENDING' AND f.scheduled_at>=${at}`;}else if(scope==='overdue'){const now=position();params.push(new Date());clause=`f.status='PENDING' AND f.scheduled_at<${now}`;}else if(scope==='completed'){clause="f.status='COMPLETED'";}else{const start=position();params.push(day.start);const end=position();params.push(day.end);clause=`f.status='PENDING' AND f.scheduled_at>=${start} AND f.scheduled_at<${end}`;}const ownerClause=own?'f.assigned_to=$1 AND ':'';const rows=(await db.query(`SELECT f.*,l.name,l.contact,l.lead_type,l.workflow_status,l.serial_no,u.name assigned_name FROM followups f JOIN leads l ON l.id=f.lead_id JOIN users u ON u.id=f.assigned_to WHERE ${ownerClause}${clause} ORDER BY f.scheduled_at`,params)).rows;res.json({followups:rows});}));

  app.post('/api/followups/:id/complete',asyncRoute(async(req,res)=>{const parsed=z.object({remark:z.string().trim().min(1,'An outcome remark is required').max(1000),leadType:leadType.optional(),nextStage:workflowStatus.optional(),scheduledAt:z.string().datetime().optional(),projectName:z.string().trim().max(150).optional(),lostReason:lostReason.optional(),lostReasonDetail:z.string().trim().max(250).optional()}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:parsed.error.issues[0]?.message});const item=(await db.query<any>(`SELECT * FROM followups WHERE id=$1 AND status='PENDING'${isManager(req.user!.role)?'':' AND assigned_to=$2'}`,isManager(req.user!.role)?[req.params.id]:[req.params.id,req.user!.id])).rows[0];if(!item)return res.status(404).json({error:'Pending follow-up not found'});const current=(await db.query<any>('SELECT * FROM leads WHERE id=$1 AND archived_at IS NULL',[item.lead_id])).rows[0];if(!current)return res.status(404).json({error:'Lead not found'});const next=parsed.data.nextStage;const allowed:Record<string,string[]>={FOLLOW_UP:['FOLLOW_UP','SITE_VISIT','OFFICE_VISIT','LOST'],SITE_VISIT:['FOLLOW_UP','SITE_VISIT','OFFICE_VISIT','WON','LOST'],OFFICE_VISIT:['FOLLOW_UP','SITE_VISIT','OFFICE_VISIT','WON','LOST']};if(next&&!allowed[current.workflow_status]?.includes(next))return res.status(400).json({error:`Choose a valid next action after ${stageLabel(current.workflow_status)}`});if(next&&['FOLLOW_UP','SITE_VISIT','OFFICE_VISIT'].includes(next)&&!parsed.data.scheduledAt)return res.status(400).json({error:'Choose the next action date and time'});if(parsed.data.scheduledAt&&new Date(parsed.data.scheduledAt).getTime()<Date.now()-60000)return res.status(400).json({error:'Next action time must be in the future'});if(next==='SITE_VISIT'&&!parsed.data.projectName)return res.status(400).json({error:'Project is required for a site visit'});if(next==='LOST'&&!parsed.data.lostReason)return res.status(400).json({error:'Choose a lost reason'});if(next==='LOST'&&parsed.data.lostReason==='OTHER'&&!parsed.data.lostReasonDetail)return res.status(400).json({error:'Describe the other lost reason'});await transaction(db,async client=>{await client.query("UPDATE followups SET status='COMPLETED',completed_at=CURRENT_TIMESTAMP,completion_remark=$1,updated_at=CURRENT_TIMESTAMP WHERE id=$2",[parsed.data.remark,item.id]);await client.query('UPDATE notifications SET is_read=TRUE WHERE followup_id=$1',[item.id]);await client.query("INSERT INTO lead_activities(lead_id,user_id,type,content) VALUES ($1,$2,'FOLLOWUP_COMPLETED',$3)",[item.lead_id,req.user!.id,parsed.data.remark]);if(parsed.data.leadType&&current.lead_type!==parsed.data.leadType){await client.query('UPDATE leads SET lead_type=$1,updated_at=CURRENT_TIMESTAMP WHERE id=$2',[parsed.data.leadType,item.lead_id]);await client.query("INSERT INTO lead_activities(lead_id,user_id,type,content) VALUES ($1,$2,'TYPE_CHANGED',$3)",[item.lead_id,req.user!.id,`Lead type changed from ${current.lead_type} to ${parsed.data.leadType}`]);}if(next){const metadata={fromStage:current.workflow_status,toStage:next,scheduledAt:parsed.data.scheduledAt,projectName:parsed.data.projectName,lostReason:parsed.data.lostReason,lostReasonDetail:parsed.data.lostReasonDetail,completedFollowupId:item.id};await client.query(`UPDATE leads SET workflow_status=$1,status=$2,lost_reason=$3,lost_reason_detail=$4,project_name=COALESCE($5,project_name),site_visit_at=CASE WHEN $1='SITE_VISIT' THEN $6::timestamptz ELSE site_visit_at END,office_visit_at=CASE WHEN $1='OFFICE_VISIT' THEN $6::timestamptz ELSE office_visit_at END,pipeline_updated_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=$7`,[next,next==='WON'?'CONVERTED':next==='LOST'?'INACTIVE':'ACTIVE',next==='LOST'?parsed.data.lostReason:null,next==='LOST'?parsed.data.lostReasonDetail||null:null,parsed.data.projectName||null,parsed.data.scheduledAt||null,item.lead_id]);await client.query("INSERT INTO lead_activities(lead_id,user_id,type,content,metadata) VALUES ($1,$2,'STAGE_CHANGED',$3,$4)",[item.lead_id,req.user!.id,`${stageLabel(current.workflow_status)} → ${stageLabel(next)} — ${parsed.data.remark}`,metadata]);if(['FOLLOW_UP','SITE_VISIT','OFFICE_VISIT'].includes(next))await upsertPipelineReminder(client,item.lead_id,current.assigned_to,req.user!.id,next as 'FOLLOW_UP'|'SITE_VISIT'|'OFFICE_VISIT',parsed.data.scheduledAt!,parsed.data.remark);}await audit(client,req.user!.id,'FOLLOWUP_COMPLETED','FOLLOWUP',item.id,{leadId:item.lead_id,nextStage:next,scheduledAt:parsed.data.scheduledAt});});res.json({success:true});}));
