  app.post('/api/inventory/payment-plans',asyncRoute(async(req,res)=>{if(!isManager(req.user!.role))return res.status(403).json({error:'Only administrators and managers can create payment plans'});const parsed=z.object({projectId:z.coerce.number().int().positive(),name:z.string().trim().min(2).max(150),description:z.string().trim().max(800).default(''),milestones:z.array(z.object({label:z.string().trim().min(2).max(120),percentage:z.coerce.number().positive().max(100),dueDays:z.coerce.number().int().min(0).max(3650).default(0)})).min(1)}).refine(v=>Math.abs(v.milestones.reduce((sum,m)=>sum+m.percentage,0)-100)<0.01,{message:'Payment plan milestone percentages must total 100'}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:parsed.error.issues[0]?.message});const plan=await transaction(db,async client=>{const item=(await client.query<any>('INSERT INTO payment_plans(project_id,name,description,created_by) VALUES ($1,$2,$3,$4) RETURNING *',[parsed.data.projectId,parsed.data.name,parsed.data.description,req.user!.id])).rows[0];for(const [index,m] of parsed.data.milestones.entries())await client.query('INSERT INTO payment_plan_milestones(payment_plan_id,label,percentage,due_days,sequence) VALUES ($1,$2,$3,$4,$5)',[item.id,m.label,m.percentage,m.dueDays,index+1]);return item;});res.status(201).json({plan});}));
